package main

import (
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"math"
	"testing"
	"time"
)

func TestOriginalPhysicsTrace(t *testing.T) {
	// Reference trace generated by compiling the corresponding functions from
	// the supplied flappybird.c with -ffp-contract=off and the Compás musl RNG.
	const expected = "1aaec7067c99e3b8440f7038ff0608e84f604c8abc79bed338dd755ca0aa5a59"
	trace := sha256.New()
	var buf [33 * 4]byte
	for _, height := range []int{720, 800} {
		for _, seed := range []int64{0, 1, 0xdeadbeef} {
			for profile := 0; profile < 45; profile++ {
				g := newGame(playfieldHeight(480, height), 0, seed)
				for tick := 0; tick < 1000; tick++ {
					traceInput(g, tick, profile)
					if g.step() {
						g.bestPending = false
					}
					result := [...]int{
						int(g.state), g.birdY, int(math.Float32bits(g.speed)),
						int(math.Float32bits(g.acceleration)), int(math.Float32bits(g.angle)),
						int(math.Float32bits(g.turn)), g.score, g.best, g.bestBefore,
						g.scroll, g.background, g.bobDegrees, int(g.wings), g.wingMS, g.wingIndex,
						g.wingFrame(), g.overTick, g.fadeTick, bit(g.changeToReady), bit(g.keepLook),
						bit(g.bestPending), g.floor, int(uint32(g.rng)), int(uint32(g.rng >> 32)),
						g.gates[0].x, g.gates[0].gapTop, bit(g.gates[0].passed),
						g.gates[1].x, g.gates[1].gapTop, bit(g.gates[1].passed),
						g.gates[2].x, g.gates[2].gapTop, bit(g.gates[2].passed),
					}
					for i, field := range result {
						binary.LittleEndian.PutUint32(buf[i*4:], uint32(field))
					}
					trace.Write(buf[:])
				}
			}
		}
	}
	if got := fmt.Sprintf("%x", trace.Sum(nil)); got != expected {
		t.Fatalf("physics trace changed: got %s, want %s", got, expected)
	}
}

func bit(v bool) int {
	if v {
		return 1
	}
	return 0
}

func traceInput(g *game, tick, profile int) {
	if g.fadeTick >= 0 {
		return
	}
	switch {
	case g.canStart(), g.state == ready && g.bobDegrees == profile*8:
		g.action()
	case g.state == flying:
		target, nearest := g.floor/2, 9999
		for _, p := range g.gates {
			if p.x+gateWidth >= birdLeft && p.x < nearest {
				nearest = p.x
				target = p.gapTop + (gateGap-birdBox)/2
			}
		}
		if (profile%4 == 1 && tick%7 == 0) ||
			(profile%4 == 2 && tick%19 == 0) ||
			(profile%4 == 3 && g.birdY >= target && g.speed >= 0) {
			g.action()
		}
	}
}

func TestOriginalTickThresholds(t *testing.T) {
	for _, tc := range []struct {
		us, steps int
	}{{16000, 1}, {25001, 1}, {49999, 1}, {50000, 3}, {58335, 4}, {250000, 4}, {250001, 0}} {
		if actual := stepsFor(time.Duration(tc.us) * time.Microsecond); actual != tc.steps {
			t.Errorf("%d us produced %d steps, want %d", tc.us, actual, tc.steps)
		}
	}
}

func TestBestScoreReopens(t *testing.T) {
	dir := t.TempDir()
	if err := saveBest(dir, 5); err != nil {
		t.Fatal(err)
	}
	if err := saveBest(dir, 9); err != nil {
		t.Fatal(err)
	}
	if best := loadBest(dir); best != 9 {
		t.Fatalf("reopened best is %d, want 9", best)
	}
}
